def find_all_good_up_to(max_digits):
    good = set()
    # 1-digit
    for i in range(1, 10):
        good.add(i)

    for length in range(2, max_digits + 1):
        new_good = set()
        for m_prime in good:
            s_prime = str(m_prime)
            # To ensure m_new has 'length' digits, we might need to be careful.
            # But the logic should naturally produce numbers with one more digit.
            for i in range(len(s_prime) + 1):
                for digit in range(1, 10):
                    s_new = s_prime[:i] + str(digit) + s_prime[i:]
                    m_new = int(s_new)

                    # Check if m_new has 'length' digits and distinct digits
                    if len(s_new) == length:
                        digits = [int(d) for d in s_new]
                        if len(set(digits)) == len(digits):
                            if m_new % m_prime == 0:
                                new_good.add(m_new)
        good.update(new_good)
    return sorted(list(good))

