def solve():
    best_m = 0
    for j in range(1, 8):
        for d_j in range(1, 10):
            for A_digits in itertools.permutations(range(1, 10), j):
                A = int("".join(map(str, A_digits)))
                X = d_j * (10**j) - 9 * A
                if X == 0: continue

                divs = []
                for i in range(1, int(abs(X)**0.5) + 1):
                    if X % i == 0:
                        divs.append(i)
                        divs.append(abs(X) // i)

                for m_prime in set(divs):
                    if m_prime <= 0: continue
                    if (m_prime - A) % (10**j) == 0:
                        B = (m_prime - A) // (10**j)
                        if B > 0:
                            m = B * (10**(j+1)) + d_j * (10**j) + A
                            s_m = str(m)

                            # Check conditions:
                            # 1. Distinct nonzero digits in m
                            # 2. m_prime is good
                            # 3. m' is obtained by removing d_j at position j
                            # 4. m has no 0s

                            if len(set(s_m)) == len(s_m) and '0' not in s_m:
                                # check if removing digit at position j gives m_prime
                                # position j from the right (0-indexed)
                                # The digit at position j from the right is s_m[len(s_m)-1-j]
                                if s_m[len(s_m)-1-j] == str(d_j):
                                    # m' should be s_m with that digit removed
                                    m_prime_from_m = int(s_m[:len(s_m)-1-j] + s_m[len(s_m)-j:])
                                    if m_prime_from_m == m_prime:
                                        if is_good(m_prime):
                                            if m > best_m:
                                                best_m = m
    print(best_m)

